<button class="ce-save" type="submit">Update capability</button></form><script>const matters=document.getElementById("representative-matters");if(matters){matters.value=matters.value.split(/\r?\n/).filter(line=>line.trim()).map(line=>line.replace(/^\s*[•\-]\s*/,"• ")).join("\n");matters.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();const start=matters.selectionStart,end=matters.selectionEnd;matters.value=matters.value.slice(0,start)+"\n• "+matters.value.slice(end);matters.selectionStart=matters.selectionEnd=start+3;}});matters.form.addEventListener("submit",()=>{matters.value=matters.value.split(/\r?\n/).map(line=>line.replace(/^\s*•\s*/,"").trim()).filter(Boolean).join("\n");});}</script><script>document.getElementById("experience").value=document.getElementById("experience").value.replace(/\\n/g,"\n");</script><script>const list=document.getElementById("advise-points"),hidden=document.getElementById("experience");function row(title="",description=""){const item=document.createElement("div");item.className="point-row";item.innerHTML=`<label>Heading</label><input class="point-title" placeholder="Commercial Agreements" value=""><label>Point / Description</label><textarea class="point-description" placeholder="Structuring, drafting, and negotiating agreements..."></textarea><button type="button" class="point-remove">Remove</button>`;item.querySelector(".point-title").value=title;item.querySelector(".point-description").value=description;item.querySelector(".point-remove").onclick=()=>item.remove();list.appendChild(item)}const existing=hidden.value.split(/\r?\n/).filter(Boolean);existing.forEach(line=>{const parts=line.split(" — ");row(parts.shift(),parts.join(" — "))});if(!existing.length)row();document.getElementById("add-advise-point").onclick=()=>row();document.querySelector("form").addEventListener("submit",()=>{hidden.value=[...list.querySelectorAll(".point-row")].map(item=>{const t=item.querySelector(".point-title").value.trim(),d=item.querySelector(".point-description").value.trim();return t&&d?`${t} — ${d}`:""}).filter(Boolean).join("\n")});</script></div></main></body></html>
